import React, { useState, useEffect } from 'react';
import './ThemeSwitcher.css';

const ThemeSwitcher = () => {
  const [theme, setTheme] = useState('purple');

  useEffect(() => {
    // Check localStorage first
    const savedTheme = localStorage.getItem('app-theme');
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else {
      // Fall back to system preference
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      const systemTheme = prefersDark ? 'purple' : 'teal';
      setTheme(systemTheme);
      applyTheme(systemTheme);
    }
  }, []);

  const applyTheme = (themeName) => {
    // Remove existing theme stylesheets
    const existingLink = document.getElementById('theme-stylesheet');
    if (existingLink) {
      existingLink.remove();
    }

    // Create and load new theme stylesheet
    const link = document.createElement('link');
    link.id = 'theme-stylesheet';
    link.rel = 'stylesheet';

    if (themeName === 'teal') {
      link.href = '/src/styles/ThemeTealCoral-GlobalStyle.css';
    } else {
      // Purple theme - use original styles (or create purple-specific file)
      link.href = '/src/styles/GlobalStyle.css';
    }

    document.head.appendChild(link);

    // Load Projects page theme CSS
    const projectsLink = document.getElementById('theme-projects-stylesheet');
    if (projectsLink) {
      projectsLink.remove();
    }

    const projectsStyleLink = document.createElement('link');
    projectsStyleLink.id = 'theme-projects-stylesheet';
    projectsStyleLink.rel = 'stylesheet';

    if (themeName === 'teal') {
      projectsStyleLink.href = '/src/styles/ThemeTealCoral-ProjectsPage.css';
    } else {
      projectsStyleLink.href = '/src/styles/ProjectsPage.css';
    }

    document.head.appendChild(projectsStyleLink);

    // Set data attribute for reference
    document.documentElement.setAttribute('data-theme', themeName);
    localStorage.setItem('app-theme', themeName);
  };

  const handleToggle = () => {
    const newTheme = theme === 'purple' ? 'teal' : 'purple';
    setTheme(newTheme);
    applyTheme(newTheme);

    // Announce to screen readers
    const announcement = `Theme set to ${newTheme.charAt(0).toUpperCase() + newTheme.slice(1)}`;
    announceToScreenReader(announcement);
  };

  const announceToScreenReader = (message) => {
    const liveRegion = document.getElementById('theme-announcer');
    if (liveRegion) {
      liveRegion.textContent = message;
    }
  };

  return (
    <>
      {/* Invisible live region for screen reader announcements */}
      <div
        id="theme-announcer"
        className="sr-only"
        role="status"
        aria-live="polite"
        aria-atomic="true"
      />

      {/* Theme Toggle Button */}
      <button
        className="theme-switcher"
        onClick={handleToggle}
        aria-label="Toggle site theme"
        aria-pressed={theme === 'teal'}
        title={`Current theme: ${theme}`}
      >
        <div className="theme-switcher-pill">
          {/* Purple side */}
          <div className="theme-switcher-side theme-switcher-side--purple" />

          {/* Teal side */}
          <div className="theme-switcher-side theme-switcher-side--teal" />

          {/* Animated knob */}
          <div
            className={`theme-switcher-knob theme-switcher-knob--${theme}`}
            aria-hidden="true"
          />
        </div>
      </button>
    </>
  );
};

export default ThemeSwitcher;
